1	// contractlab —— 可热更新的本地接口场景服务
2	//
3	// 运行环境：Node.js 24（内置 TypeScript 类型擦除，可直接 `node app.ts`），
4	// 无任何外部运行依赖。
5	//
6	// 行为约定（详见 README.md）：
7	// - 业务接口由“方法 + 绝对路径”唯一标识，查询串不参与匹配，不支持路径模板；
8	// - 请求被完整接收后，才按当前配置匹配接口并同步“预留”响应序列的下一项，
9	//   序列耗尽后持续返回末项；预留之后客户端断开，仍计为一次消费；
10	// - POST /__contractlab/reload 重新读取同一配置文件：新配置全部有效时才
11	//   原子替换全部接口、重置全部序列并递增版本号；失败时现状不变；
12	// - 在途请求持有预留时的旧响应快照（状态码/响应头/正文/延迟/版本），
13	//   完成时不会推进新序列；
14	// - POST 接口可附加可选的 requestBody 正文结构规则：请求完整接收后先校验
15	//   媒体类型与 JSON 结构，不符时返回 400 差异报告，不发送场景响应、不消费序列；
16	//   校验通过才按“完整接收”顺序预留响应项。任意规则节点可附布尔 nullable：
17	//   true 在原接受集合上加入 null（必填字段仍不得缺失，空正文不等于 null）；
18	//   标量节点可附非空 enum 候选数组：接受集合为“类型及可空集合”与枚举集合的
19	//   交集（可空不越过枚举；object/array 节点禁止 enum）。
20	// - 管理入口 GET /__contractlab/requests 查询本次进程内的请求记录（一致快照、
21	//   不推进序列），POST /__contractlab/requests/clear 清空记录；记录只存在内存中，
22	//   管理范围（/__contractlab 本身及 /__contractlab/ 前缀）的请求一律不记录。
23	// - compare 子命令：离线比较旧、新两份场景文件，判断沿用旧接口约定的客户端
24	//   是否仍能调用新版；报告写 stdout，不启动监听、不修改文件。
25	// - import 子命令：读取本地 OpenAPI 3.0 JSON 与现有场景配置，按“方法 + 字面
26	//   路径”选择文档操作，仅用操作 requestBody 转换出的正文规则替换各接口的
27	//   requestBody（保留接口顺序与 responses），新场景 JSON 写 stdout。
28	// - verify 子命令：离线批量请求校验。读取 GET /__contractlab/requests 的完整
29	//   JSON 快照与一份场景配置，按输入顺序保留原编号逐条重新判定（仅依据记录中的
30	//   原始请求重新计算，不信任原版本、匹配/校验结论、计划响应与发送状态）；
31	//   报告写 stdout，不监听、不发送请求、不修改文件。
32	// - replay 子命令：本机请求重放与响应差异报告。读取同一份请求记录快照，
33	//   按输入顺序把每条记录的原始请求逐条重放到 127.0.0.1 的指定端口
34	//   （每条只尝试一次、不跟随重定向、每条有覆盖完整收发的总超时），
35	//   仅比较实际响应的状态码与正文原始字节和记录中的计划响应；
36	//   报告写 stdout，不监听、不修改文件。
37	
38	import http from 'node:http';
39	import { readFile } from 'node:fs/promises';
40	import path from 'node:path';
41	
42	const APP_NAME = 'contractlab';
43	
44	// 管理入口（保留前缀，业务接口不得使用）
45	const ADMIN_PREFIX = '/__contractlab/';
46	const ADMIN_BASE = '/__contractlab';
47	const HEALTH_PATH = '/__contractlab/health';
48	const RELOAD_PATH = '/__contractlab/reload';
49	const REQUESTS_PATH = '/__contractlab/requests';
50	const REQUESTS_CLEAR_PATH = '/__contractlab/requests/clear';
51	
52	// 每个业务响应都携带当前配置版本
53	const VERSION_HEADER = 'X-Contractlab-Version';
54	
55	// 请求体上限（本机工具的防误操作保护，超出直接 413，不触碰任何序列）
56	const MAX_BODY_BYTES = 100 * 1024 * 1024;
57	
58	// 由服务器管理、业务配置不得覆盖的“传输头”（大小写不敏感）
59	const BLOCKED_HEADERS = new Set([
60	  'connection',
61	  'keep-alive',
62	  'content-length',
63	  'transfer-encoding',
64	]);
65	
66	// RFC 7230 token：合法的 HTTP 头名称字符
67	const HEADER_NAME_RE = /^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/;
68	
69	type HttpMethod = 'GET' | 'POST';
70	
71	// ---------------------------------------------------------------------------
72	// 请求正文结构规则（endpoints[].requestBody，仅 POST）
73	// ---------------------------------------------------------------------------
74	//
75	// 规则格式（JSON 对象，未知字段一律拒绝）：
76	//   { "type": "object", "fields": { "<名>": <字段规则>, ... }, "additionalProperties": false }
77	//   { "type": "array", "items": <规则> }
78	//   { "type": "string" | "number" | "integer" | "boolean" | "null" }
79	// 任意规则节点（根、字段、数组元素）可附布尔 "nullable"：省略或 false 行为不变，
80	// true 在原接受集合上加入 null（type:null 本就只接受 null）。必填字段即使可空也
81	// 不能缺失；null 被接受时不产生子节点差异，非 null 值仍须通过全部原约束。
82	// 标量节点（string/number/integer/boolean/null）可附非空 "enum" 候选数组：
83	// 每项须符合节点类型与可空约定（null 项要求 nullable:true 或 type:null），
84	// 顺序与重复值不影响语义（数字按数值相等，0 与 -0 等价，不做类型转换）；
85	// 有 enum 时接受集合为“类型及可空集合”与枚举集合的交集（可空不越过枚举）。
86	// object / array 节点禁止 enum。
87	// 字段规则 = 任意规则 + 可选 "required": true（缺省为可缺省）；
88	// object 的 fields / additionalProperties 可省略（默认无字段声明、拒绝未声明字段）；
89	// array 必须声明 items。
90	
91	type ScalarKind = 'string' | 'number' | 'integer' | 'boolean' | 'null';
92	
93	// 枚举候选值：标量字面量（含 null，仅当节点可空或 type:null 时允许）
94	type EnumValue = string | number | boolean | null;
95	
96	type BodyRule =
97	  | {
98	      readonly kind: 'object';
99	      readonly fields: ReadonlyMap<string, FieldRule>;
100	      readonly additionalProperties: boolean;
101	      readonly nullable: boolean;
102	    }
103	  | { readonly kind: 'array'; readonly items: BodyRule; readonly nullable: boolean }
104	  | {
105	      readonly kind: ScalarKind;
106	      readonly nullable: boolean;
107	      // 非空候选数组（已按数值相等去重）；undefined 表示无枚举限制
108	      readonly enum: readonly EnumValue[] | undefined;
109	    };
110	
111	interface FieldRule {
112	  readonly rule: BodyRule;
113	  readonly required: boolean;
114	}
115	
116	interface ResponseSpec {
117	  readonly status: number;
118	  readonly headers: { readonly [name: string]: string };
119	  readonly body: string;
120	  readonly delay: number;
121	}
122	
123	interface EndpointSpec {
124	  readonly method: HttpMethod;
125	  readonly path: string;
126	  readonly responses: readonly ResponseSpec[];
127	  readonly bodyRule: BodyRule | undefined;
128	}
129	
130	interface LiveEndpoint {
131	  readonly key: string;
132	  readonly responses: readonly ResponseSpec[];
133	  readonly bodyRule: BodyRule | undefined;
134	  // 下一个待预留位置；到达末项后停在末项（持续复用）
135	  cursor: number;
136	}
137	
138	interface LiveState {
139	  readonly version: number;
140	  readonly endpoints: ReadonlyMap<string, LiveEndpoint>;
141	}
142	
143	interface ReloadResult {
144	  ok: boolean;
145	  version: number;
146	  error?: string;
147	}
148	
149	class ConfigError extends Error {
150	  constructor(message: string) {
151	    super(message);
152	    this.name = 'ConfigError';
153	  }
154	}
155	
156	// ---------------------------------------------------------------------------
157	// 配置校验
158	// ---------------------------------------------------------------------------
159	
160	function isPlainObject(value: unknown): value is Record<string, unknown> {
161	  return typeof value === 'object' && value !== null && !Array.isArray(value);
162	}
163	
164	function validatePath(p: string, where: string): void {
165	  if (p.length === 0 || p[0] !== '/') {
166	    throw new ConfigError(`${where}.path 必须是以 "/" 开头的绝对路径，收到 "${p}"`);
167	  }
168	  if (p.length > 4096) {
169	    throw new ConfigError(`${where}.path 过长（最多 4096 字符）`);
170	  }
171	  for (const ch of p) {
172	    const code = ch.charCodeAt(0);
173	    if (ch === '?' || ch === '#' || ch === '{' || ch === '}') {
174	      throw new ConfigError(
175	        `${where}.path "${p}" 含有非法字符 "${ch}"：查询串不参与匹配，且不支持路径模板`,
176	      );
177	    }
178	    if (code <= 0x1f || code === 0x7f || code === 0x20) {
179	      throw new ConfigError(`${where}.path "${p}" 不得包含空白或控制字符`);
180	    }
181	  }
182	}
183	
184	function validateResponse(raw: unknown, where: string): ResponseSpec {
185	  if (!isPlainObject(raw)) {
186	    throw new ConfigError(`${where} 必须是对象`);
187	  }
188	  for (const key of Object.keys(raw)) {
189	    if (key !== 'status' && key !== 'headers' && key !== 'body' && key !== 'delay') {
190	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
191	    }
192	  }
193	
194	  const { status, headers, body, delay } = raw;
195	
196	  if (!Number.isInteger(status) || status < 200 || status > 599) {
197	    throw new ConfigError(`${where}.status 必须是 200 至 599 之间的整数，收到 ${JSON.stringify(status)}`);
198	  }
199	
200	  if (!isPlainObject(headers)) {
201	    throw new ConfigError(`${where}.headers 必须是字符串键值对象`);
202	  }
203	  // 无原型对象：名为 "__proto__" 的头也按自有字段保留，不被原型 setter 吞掉
204	  const cleanHeaders: { [name: string]: string } = Object.create(null);
205	  const seenNames = new Set<string>();
206	  for (const [name, value] of Object.entries(headers)) {
207	    const whereHeader = `${where}.headers["${name}"]`;
208	    if (!HEADER_NAME_RE.test(name)) {
209	      throw new ConfigError(`${whereHeader} 不是合法的 HTTP 响应头名称`);
210	    }
211	    const lower = name.toLowerCase();
212	    if (BLOCKED_HEADERS.has(lower)) {
213	      throw new ConfigError(`${whereHeader} 属于服务器管理的传输头，不允许在配置中设置`);
214	    }
215	    if (seenNames.has(lower)) {
216	      throw new ConfigError(`${whereHeader} 与同序列内另一个响应头仅大小写不同，视为重复`);
217	    }
218	    if (typeof value !== 'string') {
219	      throw new ConfigError(`${whereHeader} 的值必须是字符串`);
220	    }
221	    for (let i = 0; i < value.length; i += 1) {
222	      const code = value.charCodeAt(i);
223	      // 允许水平制表符(0x09)；拒绝换行及其余控制字符；
224	      // Node 的 HTTP 头值只支持 Latin-1（0x80-0xFF），更高码位发送时会抛错
225	      if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
226	        throw new ConfigError(
227	          `${whereHeader} 的值不得包含换行或其他控制字符，且只能使用 Latin-1 字符`,
228	        );
229	      }
230	    }
231	    seenNames.add(lower);
232	    cleanHeaders[name] = value;
233	  }
234	
235	  if (typeof body !== 'string') {
236	    throw new ConfigError(`${where}.body 必须是文本字符串`);
237	  }
238	  if ((status === 204 || status === 304) && body !== '') {
239	    throw new ConfigError(`${where}.body 状态码为 ${status} 时正文必须为空字符串`);
240	  }
241	
242	  if (!Number.isInteger(delay) || delay < 0 || delay > 60000) {
243	    throw new ConfigError(`${where}.delay 必须是 0 至 60000 之间的整数毫秒数，收到 ${JSON.stringify(delay)}`);
244	  }
245	
246	  return { status, headers: cleanHeaders, body, delay };
247	}
248	
249	const SCALAR_KINDS: ReadonlySet<string> = new Set([
250	  'string',
251	  'number',
252	  'integer',
253	  'boolean',
254	  'null',
255	]);
256	
257	// 枚举项是否满足节点类型（不做类型转换；number 限有限数字、integer 限整数）
258	function enumItemConforms(kind: ScalarKind, item: unknown): boolean {
259	  switch (kind) {
260	    case 'string':
261	      return typeof item === 'string';
262	    case 'number':
263	      return typeof item === 'number' && Number.isFinite(item);
264	    case 'integer':
265	      return Number.isInteger(item);
266	    case 'boolean':
267	      return typeof item === 'boolean';
268	    case 'null':
269	      return item === null;
270	  }
271	}
272	
273	// 校验并规范化枚举候选（场景配置与 OpenAPI 导入共用语义）：非空数组、逐项符合
274	// 节点类型与可空约定（null 项要求 nullable:true 或 type:null）、按数值相等去重
275	// （0 与 -0 等价；顺序与重复值不影响语义）。失败返回可定位的 where 与原因。
276	function enumValuesOrError(
277	  enumRaw: unknown,
278	  kind: ScalarKind,
279	  nullable: boolean,
280	  where: string,
281	): { errorWhere: string; message: string } | { values: EnumValue[] } {
282	  if (!Array.isArray(enumRaw) || enumRaw.length === 0) {
283	    return { errorWhere: where, message: '必须是非空数组（至少一个候选值）' };
284	  }
285	  // Set 按 SameValueZero 去重：0 与 -0 视为同一候选
286	  const seen = new Set<unknown>();
287	  const values: EnumValue[] = [];
288	  for (let i = 0; i < enumRaw.length; i += 1) {
289	    const item = enumRaw[i];
290	    const itemWhere = `${where}[${i}]`;
291	    if (item === null) {
292	      if (!nullable && kind !== 'null') {
293	        return {
294	          errorWhere: itemWhere,
295	          message: '为 null：接受 null 要求节点为 nullable:true 或 type:"null"',
296	        };
297	      }
298	    } else if (!enumItemConforms(kind, item)) {
299	      return {
300	        errorWhere: itemWhere,
301	        message: `必须是 ${kind}（与节点类型一致，不做类型转换），收到 ${JSON.stringify(item)}`,
302	      };
303	    }
304	    if (!seen.has(item)) {
305	      seen.add(item);
306	      values.push(item as EnumValue);
307	    }
308	  }
309	  return { values };
310	}
311	
312	function validateBodyRule(raw: unknown, where: string): BodyRule {
313	  if (!isPlainObject(raw)) {
314	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
315	  }
316	
317	  const type = raw.type;
318	  const allowed = new Set(['type', 'nullable']);
319	  if (type === 'object') {
320	    allowed.add('fields');
321	    allowed.add('additionalProperties');
322	  } else if (type === 'array') {
323	    allowed.add('items');
324	  } else if (!SCALAR_KINDS.has(type as string)) {
325	    throw new ConfigError(
326	      `${where}.type 必须是 "object" | "array" | "string" | "number" | "integer" | "boolean" | "null"，收到 ${JSON.stringify(type)}`,
327	    );
328	  } else {
329	    // enum 仅允许在标量节点上；object / array 节点声明 enum 按未知字段拒绝
330	    allowed.add('enum');
331	  }
332	  for (const key of Object.keys(raw)) {
333	    if (!allowed.has(key)) {
334	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
335	    }
336	  }
337	
338	  // 任意规则节点可附布尔 nullable：省略或 false 不变，true 在原接受集合上加入 null
339	  const nullableRaw = raw.nullable;
340	  if (nullableRaw !== undefined && typeof nullableRaw !== 'boolean') {
341	    throw new ConfigError(`${where}.nullable 必须是布尔值，收到 ${JSON.stringify(nullableRaw)}`);
342	  }
343	  const nullable = nullableRaw === true;
344	
345	  // 标量节点可附非空 enum：每项须符合节点类型与可空约定；有枚举时接受集合为
346	  // “类型及可空集合”与枚举集合的交集（可空不越过枚举，null 须列入枚举才被接受）
347	  let enumValues: readonly EnumValue[] | undefined;
348	  if (raw.enum !== undefined) {
349	    const result = enumValuesOrError(raw.enum, type as ScalarKind, nullable, `${where}.enum`);
350	    if ('errorWhere' in result) {
351	      throw new ConfigError(`${result.errorWhere} ${result.message}`);
352	    }
353	    enumValues = result.values;
354	  }
355	
356	  if (type === 'object') {
357	    const fieldsRaw = raw.fields;
358	    const fields = new Map<string, FieldRule>();
359	    if (fieldsRaw !== undefined) {
360	      if (!isPlainObject(fieldsRaw)) {
361	        throw new ConfigError(`${where}.fields 必须是对象（字段名 → 字段规则）`);
362	      }
363	      for (const [name, fieldRaw] of Object.entries(fieldsRaw)) {
364	        fields.set(name, validateFieldRule(fieldRaw, `${where}.fields[${JSON.stringify(name)}]`));
365	      }
366	    }
367	    const additional = raw.additionalProperties;
368	    if (additional !== undefined && typeof additional !== 'boolean') {
369	      throw new ConfigError(`${where}.additionalProperties 必须是布尔值`);
370	    }
371	    // 未声明字段默认拒绝
372	    return { kind: 'object', fields, additionalProperties: additional === true, nullable };
373	  }
374	
375	  if (type === 'array') {
376	    if (raw.items === undefined) {
377	      throw new ConfigError(`${where}.items 数组规则必须声明元素规则`);
378	    }
379	    return { kind: 'array', items: validateBodyRule(raw.items, `${where}.items`), nullable };
380	  }
381	
382	  return { kind: type as ScalarKind, nullable, enum: enumValues };
383	}
384	
385	// 字段规则 = 任意规则 + 可选 "required"（仅允许出现在 object 的 fields 条目中）
386	function validateFieldRule(raw: unknown, where: string): FieldRule {
387	  if (!isPlainObject(raw)) {
388	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
389	  }
390	  let required = false;
391	  // 无原型对象：未知规则键 "__proto__" 必须作为自有字段保留下来，
392	  // 交由 validateBodyRule 拒绝；普通对象字面量会在复制时被原型 setter 吞掉
393	  const rest: Record<string, unknown> = Object.create(null);
394	  for (const [key, value] of Object.entries(raw)) {
395	    if (key === 'required') {
396	      if (typeof value !== 'boolean') {
397	        throw new ConfigError(`${where}.required 必须是布尔值`);
398	      }
399	      required = value;
400	    } else {

