533	interface RequestRecord {
534	  readonly id: number;
535	  readonly receivedAt: string;
536	  readonly request: {
537	    readonly method: string;
538	    // 含查询串的原始请求目标
539	    readonly target: string;
540	    readonly path: string;
541	    // 原始请求头：按在线顺序成对保留，名称大小写与重复头均不折叠
