563	// 已清空记录的投递回调落到空集合上：不取消响应，旧请求之后完成也不得重新出现。
564	class RequestLog {
565	  private records: RequestRecord[] = [];
566	  // 仍可能被投递事件更新的记录 id 集合（清空后旧 id 不在其中）
567	  private readonly live = new Map<number, RequestRecord>();
568	  private nextId = 1;
569	
570	  create(entry: {
571	    method: string;
572	    target: string;
573	    path: string;
574	    rawHeaders: readonly string[];
575	    body: Buffer;
576	    configVersion: number;
577	  }): RequestRecord {
578	    const id = this.nextId;
579	    this.nextId += 1;
580	    const record: RequestRecord = {
581	      id,
582	      receivedAt: new Date().toISOString(),
583	      request: {
584	        method: entry.method,
585	        target: entry.target,
586	        path: entry.path,
587	        rawHeaders: entry.rawHeaders,
588	        bodyBytes: entry.body.byteLength,
589	        body: encodeBodyLosslessly(entry.body),
590	      },
591	      configVersion: entry.configVersion,
592	      matched: false,
593	      endpoint: null,
594	      bodyValidationPassed: null,
595	      bodyRejection: null,
596	      sequencePosition: null,
597	      sequenceLength: null,
598	      plannedResponse: null,
599	      delivery: 'pending',
600	    };
601	    this.records.push(record);
602	    this.live.set(id, record);
603	    return record;
604	  }
605	
606	  // 写出完成；对已清空（不再存活）的记录是 no-op
607	  markDelivered(id: number, status: DeliveryStatus): void {
608	    const record = this.live.get(id);
609	    if (!record) {
610	      return;
611	    }
612	    // 一旦完成写出即为终态：之后的连接正常关闭不得回退为 interrupted
613	    if (record.delivery === 'sent') {
614	      return;
615	    }
616	    record.delivery = status;
617	  }
618	
619	  // 调用时一致快照：拷贝当前存活记录，不推进任何序列
620	  snapshot(): readonly RequestRecord[] {
621	    return [...this.records];
622	  }
623	
624	  // 清空一次移除当时全部记录（含待发送项）；不取消响应、不改配置/版本/序列。
625	  // 清空前已完整接收的请求随后完成或失败都不再出现。
626	  clear(): number {
627	    const removed = this.records.length;
628	    this.records = [];
629	    this.live.clear();
630	    return removed;
631	  }
