647	// ---------------------------------------------------------------------------
648	// 请求正文校验：媒体类型 → UTF-8 JSON 解析 → 结构比对
649	// ---------------------------------------------------------------------------
650	
651	interface StructureProblem {
652	  readonly pointer: string;
653	  readonly expected: string;
654	  readonly actual: string;
655	}
656	
657	interface BodyReport {
658	  readonly error: 'invalid_request_body';
659	  readonly stage: 'parse' | 'structure';
660	  readonly message: string;
661	  readonly problems: readonly StructureProblem[];
662	}
663	
664	function parseFailure(message: string): BodyReport {
665	  return { error: 'invalid_request_body', stage: 'parse', message, problems: [] };
666	}
667	
668	function jsonTypeOf(value: unknown): string {
669	  if (value === null) {
670	    return 'null';
671	  }
672	  if (Array.isArray(value)) {
673	    return 'array';
674	  }
675	  return typeof value;
676	}
677	
678	// RFC 6901 JSON Pointer 段转义：~ -> ~0，/ -> ~1
679	function escapePointerSegment(segment: string): string {
680	  return segment.replace(/~/g, '~0').replace(/\//g, '~1');
681	}
682	
683	// 枚举差异的期望描述：列全候选值（JSON 形式，数字 0 与 -0 都写作 0）
684	function enumExpectedText(enumValues: readonly EnumValue[]): string {
685	  return `枚举 ${JSON.stringify(enumValues)} 之一`;
686	}
687	
688	// 结构比对：父节点类型不符时只报告该节点，不再深入制造子节点错误；
689	// 字段缺失（hasOwnProperty 为假）与合法的 JSON null 分开判断。
690	// 可空规则：null 被接受时不产生任何子节点差异；非 null 继续检查全部原约束。
691	// 枚举规则：接受集合为“类型及可空集合”与枚举集合的交集——可空不越过枚举
692	// （null 须列入枚举才被接受）；类型错误只报类型差异，不重复报枚举差异。
693	function checkRule(
694	  rule: BodyRule,
695	  value: unknown,
696	  pointer: string,
697	  problems: StructureProblem[],
698	): void {
699	  if (value === null && rule.nullable) {
700	    // 可空不越过枚举：有枚举时 null 仍须在候选集合中
701	    if (rule.kind === 'object' || rule.kind === 'array') {
702	      return;
703	    }
704	    if (rule.enum === undefined || rule.enum.includes(null)) {
705	      return;
706	    }
707	    problems.push({ pointer, expected: enumExpectedText(rule.enum), actual: 'null' });
708	    return;
709	  }
710	  switch (rule.kind) {
711	    case 'string':
712	    case 'boolean':
713	      if (typeof value !== rule.kind) {
714	        problems.push({ pointer, expected: rule.kind, actual: jsonTypeOf(value) });
715	        return;
716	      }
717	      break;
718	    case 'null':
719	      if (value !== null) {
720	        problems.push({ pointer, expected: 'null', actual: jsonTypeOf(value) });
721	      }
722	      return;
723	    case 'number':
724	      if (typeof value !== 'number' || !Number.isFinite(value)) {
725	        problems.push({ pointer, expected: 'number', actual: jsonTypeOf(value) });
726	        return;
727	      }
728	      break;
729	    case 'integer':
730	      if (!Number.isInteger(value)) {
731	        problems.push({ pointer, expected: 'integer', actual: jsonTypeOf(value) });
732	        return;
733	      }
734	      break;
735	    case 'array': {
736	      if (!Array.isArray(value)) {
737	        problems.push({ pointer, expected: 'array', actual: jsonTypeOf(value) });
738	        return;
739	      }
740	      for (let i = 0; i < value.length; i += 1) {
741	        checkRule(rule.items, value[i], `${pointer}/${i}`, problems);
742	      }
743	      return;
744	    }
745	    case 'object': {
746	      if (!isPlainObject(value)) {
747	        problems.push({ pointer, expected: 'object', actual: jsonTypeOf(value) });
748	        return;
749	      }
750	      for (const [name, field] of rule.fields) {
751	        const childPointer = `${pointer}/${escapePointerSegment(name)}`;
752	        if (!Object.prototype.hasOwnProperty.call(value, name)) {
753	          if (field.required) {
754	            problems.push({
755	              pointer: childPointer,
756	              expected: `${field.rule.kind}（必填字段）`,
757	              actual: 'missing',
758	            });
759	          }
760	        } else {
761	          checkRule(field.rule, value[name], childPointer, problems);
762	        }
763	      }
764	      if (!rule.additionalProperties) {
765	        for (const key of Object.keys(value)) {
766	          if (!rule.fields.has(key)) {
767	            problems.push({
768	              pointer: `${pointer}/${escapePointerSegment(key)}`,
769	              expected: '未声明的字段（不允许）',
770	              actual: jsonTypeOf(value[key]),
771	            });
772	          }
773	        }
774	      }
775	      return;
776	    }
777	  }
778	  // 标量枚举：类型检查已通过才核对候选集合（类型错误不重复报枚举错误）；
779	  // 数字按数值相等（0 与 -0 等价），不做类型转换
780	  if (rule.enum !== undefined && !rule.enum.includes(value as EnumValue)) {
781	    problems.push({
782	      pointer,
783	      expected: enumExpectedText(rule.enum),
784	      actual: JSON.stringify(value),
785	    });
786	  }
787	}
788	
789	// 返回 null 表示校验通过；否则为可直接序列化的 400 差异报告。
790	// contentType 为在线顺序第一项 Content-Type 头值（在线：Node 对重复
791	// content-type 只保留首项；离线 verify：取 rawHeaders 中首个同名头）。
792	// 正文解码与 JSON 解析不重写原文：BOM 与空白按 UTF-8 解码的默认规则处理，
793	// 在线与离线对同一组字节给出同一结论。
794	function validateBodyWithContentType(
795	  contentType: string | undefined,
796	  body: Buffer,
797	  rule: BodyRule,
798	): BodyReport | null {
799	  const mediaType =
800	    typeof contentType === 'string' ? contentType.split(';', 1)[0].trim().toLowerCase() : '';
801	  if (mediaType !== 'application/json') {
802	    return parseFailure(
803	      typeof contentType === 'string'
804	        ? `媒体类型不符：期望 application/json（可带参数、忽略大小写），收到 "${contentType}"`
805	        : '缺少 Content-Type 头：期望 application/json（可带参数、忽略大小写）',
806	    );
807	  }
808	
809	  if (body.length === 0) {
810	    return parseFailure('请求正文为空，无法解析为 JSON');
811	  }
812	
813	  let text: string;
814	  try {
815	    text = new TextDecoder('utf-8', { fatal: true }).decode(body);
816	  } catch {
817	    return parseFailure('请求正文不是合法的 UTF-8 编码');
818	  }
819	
820	  let parsed: unknown;
821	  try {
822	    parsed = JSON.parse(text);
823	  } catch (e) {
824	    return parseFailure(`请求正文不是合法 JSON：${describeError(e)}`);
825	  }
826	
827	  const problems: StructureProblem[] = [];
828	  checkRule(rule, parsed, '', problems);
829	  if (problems.length > 0) {
830	    return {
831	      error: 'invalid_request_body',
832	      stage: 'structure',
833	      message: `请求正文与接口约定存在 ${problems.length} 处差异`,
834	      problems,
835	    };
836	  }
837	  return null;
838	}
