1136	    // number -> integer 时样本必须是非整数，否则 0 会被新规则接受
1137	    const value =
1138	      oldRule.kind === 'number' && newRule.kind === 'integer' ? 0.5 : sampleValue(oldRule);
1139	    out.push({
1140	      pointer,
1141	      value,
1142	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 ${newRule.kind}`,
1143	    });
1144	  }
