1147	// 递归判定 L(oldRule) ⊆ L(newRule)；把发现的每个反例（连同完整正文样本）推入 out。
1148	// 不变式：value 必被 oldRule 接受、被 newRule 拒绝；pointer 用 RFC 6901 定位差异。
1149	// 可空（nullable:true 或 type:null）规则的接受集合含 null：先单独比较 null 的
1150	// 接受性，再比较双方的非 null 部分——可空不能掩盖非 null 约束的变化。
1151	// 枚举（enum）规则按集合语义比较：接受集合为“类型及可空集合”与枚举集合的交集，
1152	// 枚举增删、枚举与非枚举规则交叉（如 number 枚举全为整数时兼容非枚举 integer）
1153	// 都精确判定；可空不越过枚举（null 须列入枚举才算被接受）。
1154	function collectViolations(
1155	  oldRule: BodyRule,
1156	  newRule: BodyRule,
1157	  pointer: string,
1158	  out: BodyViolation[],
1159	): void {
1160	  const oldAcceptsNull = ruleAcceptsNullValue(oldRule);
1161	  const newAcceptsNull = ruleAcceptsNullValue(newRule);
1162	  if (oldAcceptsNull && !newAcceptsNull) {
1163	    // null 本身就是完整反例；嵌套位置由外层调用方包上必要的父对象与必填字段
1164	    out.push({ pointer, value: null, message: '旧规则接受 null，新规则不接受 null' });
1165	  }
1166	  // type:null 的旧规则只接受 null（上面已比较），没有非 null 值需要再比
1167	  if (oldRule.kind === 'null') {
1168	    return;
1169	  }
1170	  // 枚举仅含 null 项的旧规则同样只接受 null：可比较的只有 null，上面已处理
1171	  if (!hasNonNullAcceptedValues(oldRule)) {
1172	    return;
1173	  }
1174	  // 新规则只接受 null：旧规则的任意非 null 样本都是反例
1175	  if (newRule.kind === 'null') {
1176	    out.push({
1177	      pointer,
1178	      value: sampleValue(oldRule),
1179	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 null`,
1180	    });
1181	    return;
1182	  }
1183	
1184	  if (newRule.kind !== 'object' && newRule.kind !== 'array') {
1185	    // 新规则是标量：旧规则为对象/数组时任何样本都被拒绝
1186	    if (oldRule.kind === 'object' || oldRule.kind === 'array') {
1187	      out.push({
1188	        pointer,
1189	        value: sampleValue(oldRule),
1190	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 ${newRule.kind}`,
1191	      });
1192	      return;
1193	    }
1194	    collectScalarViolations(oldRule, newRule, pointer, out);
1195	    return;
1196	  }
1197	
1198	  if (newRule.kind === 'array') {
1199	    if (oldRule.kind !== 'array') {
1200	      out.push({
1201	        pointer,
1202	        value: sampleValue(oldRule),
1203	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 array`,
1204	      });
1205	      return;
1206	    }
1207	    // 元素规则收紧：用非空数组 [反例] 体现（空数组双方都会接受）
1208	    const sub: BodyViolation[] = [];
1209	    collectViolations(oldRule.items, newRule.items, `${pointer}/0`, sub);
1210	    for (const s of sub) {
1211	      out.push({ pointer: s.pointer, message: s.message, value: [s.value] });
1212	    }
1213	    return;
1214	  }
1215	
1216	  // newRule.kind === 'object'
1217	  if (oldRule.kind !== 'object') {
1218	    out.push({
1219	      pointer,
1220	      value: sampleValue(oldRule),
1221	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 object`,
1222	    });
1223	    return;
1224	  }
1225	
1226	  // (a) 新规则的必填字段必须被旧规则保证存在（旧规则未声明或仅可选即存在反例）
1227	  for (const [name, newField] of newRule.fields) {
1228	    if (!newField.required) {
1229	      continue;
1230	    }
1231	    const oldField = oldRule.fields.get(name);
1232	    if (!oldField || !oldField.required) {
1233	      out.push({
1234	        pointer: `${pointer}/${escapePointerSegment(name)}`,
1235	        // 旧规则的最小样本不含可缺省/未声明字段，恰为反例
1236	        value: sampleValue(oldRule),
1237	        message: `新规则要求必填字段 ${JSON.stringify(name)}，旧规则允许缺省该字段`,
1238	      });
1239	    }
1240	  }
1241	
1242	  // (b) 旧规则声明的字段，在新规则下仍须被接受
1243	  for (const [name, oldField] of oldRule.fields) {
1244	    const childPointer = `${pointer}/${escapePointerSegment(name)}`;
1245	    const newField = newRule.fields.get(name);
1246	    if (!newField) {
1247	      if (!newRule.additionalProperties) {
1248	        out.push({
1249	          pointer: childPointer,
1250	          value: sampleObjectWith(oldRule, name, sampleValue(oldField.rule)),
1251	          message: `新规则拒绝旧规则允许的字段 ${JSON.stringify(name)}（新规则未声明且 additionalProperties 为 false）`,
1252	        });
1253	      }
1254	      continue;
1255	    }
1256	    const sub: BodyViolation[] = [];
1257	    collectViolations(oldField.rule, newField.rule, childPointer, sub);
1258	    for (const s of sub) {
1259	      out.push({
1260	        pointer: s.pointer,
1261	        message: s.message,
1262	        value: sampleObjectWith(oldRule, name, s.value),
1263	      });
1264	    }
1265	  }
1266	
1267	  // (c) 旧规则允许未声明的额外字段时，新规则必须同样放行这些字段
1268	  if (oldRule.additionalProperties) {
1269	    if (!newRule.additionalProperties) {
1270	      const name = freshFieldName(oldRule.fields, newRule.fields);
1271	      out.push({
1272	        pointer: `${pointer}/${escapePointerSegment(name)}`,
1273	        value: sampleObjectWith(oldRule, name, 0),
1274	        message: '旧规则允许未声明的额外字段，新规则拒绝（additionalProperties 为 false）',
1275	      });
1276	    } else {
1277	      // 新规则虽放行额外字段，但其新声明的字段会约束旧版原本自由的取值
1278	      for (const [name, newField] of newRule.fields) {
1279	        if (oldRule.fields.has(name)) {
1280	          continue;
1281	        }
1282	        out.push({
1283	          pointer: `${pointer}/${escapePointerSegment(name)}`,
1284	          value: sampleObjectWith(oldRule, name, violateValue(newField.rule)),
1285	          message: `旧规则对额外字段 ${JSON.stringify(name)} 不限制取值，新规则要求其为 ${kindLabel(newField.rule)}`,
1286	        });
1287	      }
1288	    }
1289	  }
1290	}
