1305	function compareEndpoint(oldEp: EndpointSpec, newEp: EndpointSpec | undefined): EndpointReport {
1306	  const base = { method: oldEp.method, path: oldEp.path };
1307	
1308	  if (!newEp) {
1309	    return {
1310	      ...base,
1311	      compatible: false,
1312	      reasons: [
1313	        { message: '新配置中不存在该接口：按 方法 + 字面路径 匹配不到，旧客户端的调用将得到 404' },
1314	      ],
1315	      example: acceptedRequestExample(oldEp),
1316	    };
1317	  }
1318	
1319	  if (!oldEp.bodyRule && !newEp.bodyRule) {
1320	    return { ...base, compatible: true, reasons: [] };
1321	  }
1322	
1323	  if (!oldEp.bodyRule && newEp.bodyRule) {
1324	    // 旧版允许任意媒体类型与正文；新版启用校验即存在被拒绝的旧请求
1325	    return {
1326	      ...base,
1327	      compatible: false,
1328	      reasons: [
1329	        {
1330	          pointer: '',
1331	          message: '旧接口不校验请求正文（任意媒体类型与正文均可），新接口启用了 requestBody 正文校验',
1332	        },
1333	      ],
1334	      example: {
1335	        ...base,
1336	        headers: { 'Content-Type': 'application/json' },
1337	        body: JSON.stringify(violateValue(newEp.bodyRule)),
1338	      },
1339	    };
1340	  }
1341	
1342	  if (oldEp.bodyRule && !newEp.bodyRule) {
1343	    return { ...base, compatible: true, reasons: [] }; // 移除规则更宽松
1344	  }
1345	
1346	  const violations: BodyViolation[] = [];
1347	  collectViolations(oldEp.bodyRule as BodyRule, newEp.bodyRule as BodyRule, '', violations);
1348	  if (violations.length === 0) {
1349	    return { ...base, compatible: true, reasons: [] };
1350	  }
1351	  return {
1352	    ...base,
1353	    compatible: false,
1354	    reasons: violations.map((v) => ({ pointer: v.pointer, message: v.message })),
1355	    example: {
1356	      ...base,
1357	      headers: { 'Content-Type': 'application/json' },
1358	      body: JSON.stringify(violations[0].value),
1359	    },
1360	  };
