1384	async function runCompare(oldArg: string, newArg: string): Promise<never> {
1385	  const oldFile = path.resolve(oldArg);
1386	  const newFile = path.resolve(newArg);
1387	
1388	  const attempt = async (
1389	    file: string,
1390	  ): Promise<{ specs?: EndpointSpec[]; error?: string }> => {
1391	    try {
1392	      return { specs: await loadSpecsFromFile(file) };
1393	    } catch (e) {
1394	      return { error: describeError(e) };
1395	    }
1396	  };
1397	
1398	  // 两份文件都完整经历 读取 -> 解析 -> 严格校验；任一失败则不输出任何报告
1399	  const [oldResult, newResult] = await Promise.all([attempt(oldFile), attempt(newFile)]);
1400	  let failed = false;
1401	  if (oldResult.error !== undefined) {
1402	    process.stderr.write(`${APP_NAME}: compare 旧文件：${oldResult.error}\n`);
1403	    failed = true;
1404	  }
1405	  if (newResult.error !== undefined) {
1406	    process.stderr.write(`${APP_NAME}: compare 新文件：${newResult.error}\n`);
1407	    failed = true;
1408	  }
1409	  if (failed) {
1410	    process.exit(2);
1411	  }
1412	
1413	  const report = compareConfigs(
1414	    oldResult.specs as EndpointSpec[],
1415	    newResult.specs as EndpointSpec[],
1416	    oldFile,
1417	    newFile,
1418	  );
1419	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
1420	  process.exit(report.compatible ? 0 : 1);
1421	}
