1575	// 解析一层 $ref：node 是“只含 $ref 的引用节点”时返回目标与新的位置/引用链，
1576	// 否则返回 null。外部引用、非法指针、目标缺失、循环引用都在此拒绝。
1577	function dereference(
1578	  node: Record<string, unknown>,
1579	  ctx: ImportCtx,
1580	  where: string,
1581	  refChain: readonly string[],
1582	): { target: unknown; where: string; refChain: readonly string[] } | null {
1583	  if (!hasOwnKey(node, '$ref')) {
1584	    return null;
1585	  }
1586	  if (Object.keys(node).length !== 1) {
1587	    importFail(ctx, where, '含 $ref 的引用节点不得包含其他字段（只允许 "$ref"）');
1588	  }
1589	  const ref = node.$ref;
1590	  if (typeof ref !== 'string' || !ref.startsWith('#')) {
1591	    importFail(
1592	      ctx,
1593	      where,
1594	      `仅支持本文件内 $ref（以 "#" 开头的 JSON Pointer），收到 ${JSON.stringify(ref)}`,
1595	    );
1596	  }
1597	  if (refChain.includes(ref as string)) {
1598	    importFail(ctx, where, `循环 $ref 引用：${[...refChain, ref].join(' -> ')}`);
1599	  }
1600	  const fragment = (ref as string).slice(1);
1601	  let target: unknown = ctx.doc;
1602	  if (fragment !== '') {
1603	    if (!fragment.startsWith('/')) {
1604	      importFail(ctx, where, `$ref "${ref as string}" 不是合法的 JSON Pointer 片段`);
1605	    }
1606	    const segments = fragment
1607	      .slice(1)
1608	      .split('/')
1609	      .map((seg) => unescapeRefSegment(seg, ref as string, ctx, where));
1610	    let traversed = '#';
1611	    for (const segment of segments) {
1612	      traversed = `${traversed}/${escapePointerSegment(segment)}`;
1613	      if (Array.isArray(target)) {
1614	        if (!/^(0|[1-9]\d*)$/.test(segment) || Number(segment) >= target.length) {
1615	          importFail(ctx, where, `$ref "${ref as string}" 的目标不存在：${traversed} 超出数组范围`);
1616	        }
1617	        target = target[Number(segment)];
1618	      } else if (isPlainObject(target)) {
1619	        if (!hasOwnKey(target, segment)) {
1620	          importFail(ctx, where, `$ref "${ref as string}" 的目标不存在：${traversed} 缺失`);
1621	        }
1622	        target = target[segment];
1623	      } else {
1624	        importFail(ctx, where, `$ref "${ref as string}" 无法继续解析：${traversed} 不是对象或数组`);
1625	      }
1626	    }
1627	  }
1628	  return { target, where: `${where} -> ${ref as string}`, refChain: [...refChain, ref as string] };
1629	}
