1694	function collectObjectLeaves(
1695	  list: readonly unknown[],
1696	  ctx: ImportCtx,
1697	  parentWhere: string,
1698	  chain: readonly string[],
1699	): ObjectLeaf[] {
1700	  const leaves: ObjectLeaf[] = [];
