1702	    const branchWhere = `${parentWhere}.allOf[${i}]`;
1703	    const { n, nodeWhere, chain: ch } = resolveSchemaNode(raw, ctx, branchWhere, chain);
1704	    if (hasOwnKey(n, 'allOf')) {
1705	      leaves.push(...collectObjectLeaves(comboList(n, ctx, nodeWhere), ctx, nodeWhere, ch));
