2988	type ReplayResultEntry =
2989	  | {
2990	      readonly id: number;
2991	      readonly outcome: 'same';
2992	      readonly response: ReturnType<typeof replayResponseJson>;
2993	    }
2994	  | {
2995	      readonly id: number;
2996	      readonly outcome: 'different';
2997	      // 差异点：状态码不同 / 正文原始字节不同（可同时为真）
2998	      readonly differences: { readonly status: boolean; readonly body: boolean };
2999	      readonly planned: ReturnType<typeof replayResponseJson>;
3000	      readonly response: ReturnType<typeof replayResponseJson>;
3001	    }
3002	  | { readonly id: number; readonly outcome: 'failed'; readonly reason: string };
