3004	interface ReplayReport {
3005	  readonly requestsFile: string;
3006	  readonly port: number;
3007	  readonly timeoutMs: number;
3008	  readonly total: number;
3009	  readonly same: number;
3010	  readonly different: number;
3011	  readonly failed: number;
3012	  readonly results: readonly ReplayResultEntry[];
3013	}
