3015	async function runReplay(requestsArg: string, port: number, timeoutMs: number): Promise<never> {
3016	  const requestsFile = path.resolve(requestsArg);
3017	
3018	  // 参数与全部记录有效后才连接：任何快照错误都不发任何请求
3019	  let requests: ReplayRequest[];
3020	  try {
3021	    requests = await loadReplaySnapshotFromFile(requestsFile);
3022	  } catch (e) {
3023	    process.stderr.write(`${APP_NAME}: replay 请求快照：${describeError(e)}\n`);
3024	    process.exit(2);
3025	  }
3026	
3027	  // 按输入顺序保留原编号逐条重放：前一条结束才发下一条
3028	  const results: ReplayResultEntry[] = [];
3029	  for (const request of requests) {
3030	    const exchange = await replayOne(port, request, timeoutMs);
3031	    if (!exchange.ok) {
3032	      results.push({ id: request.id, outcome: 'failed', reason: exchange.reason });
3033	      continue;
3034	    }
3035	    const { response } = exchange;
3036	    // 仅比较状态码与正文原始字节；计划正文按 UTF-8 编码
3037	    const statusDiff = response.status !== request.plannedStatus;
3038	    const bodyDiff = !response.body.equals(Buffer.from(request.plannedBody, 'utf8'));
3039	    if (!statusDiff && !bodyDiff) {
3040	      results.push({ id: request.id, outcome: 'same', response: replayResponseJson(response) });
3041	    } else {
3042	      results.push({
3043	        id: request.id,
3044	        outcome: 'different',
3045	        differences: { status: statusDiff, body: bodyDiff },
3046	        planned: {
3047	          status: request.plannedStatus,
3048	          body: { encoding: 'utf-8', content: request.plannedBody },
3049	        },
3050	        response: replayResponseJson(response),
3051	      });
3052	    }
3053	  }
3054	
3055	  const same = results.filter((r) => r.outcome === 'same').length;
3056	  const different = results.filter((r) => r.outcome === 'different').length;
3057	  const failed = results.filter((r) => r.outcome === 'failed').length;
3058	  const report: ReplayReport = {
3059	    requestsFile,
3060	    port,
3061	    timeoutMs,
3062	    total: results.length,
3063	    same,
3064	    different,
3065	    failed,
3066	    results,
3067	  };
3068	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
3069	  // 空快照或全部相同退出 0；存在差异或通信失败退出 1
3070	  process.exit(different === 0 && failed === 0 ? 0 : 1);
3071	}
