3274	// 完整接收请求体；未完整接收即断开返回 'aborted'（调用方不得推进序列）
3275	function receiveBody(req: http.IncomingMessage, res: http.ServerResponse): Promise<ReceivedBody> {
3276	  return new Promise((resolve) => {
3277	    let settled = false;
3278	    let size = 0;
3279	    const chunks: Buffer[] = [];
3280	    const finish = (outcome: BodyOutcome): void => {
3281	      if (!settled) {
3282	        settled = true;
3283	        resolve({ outcome, body: outcome === 'received' ? Buffer.concat(chunks) : Buffer.alloc(0) });
3284	      }
3285	    };
3286	    req.on('data', (chunk: Buffer) => {
3287	      size += chunk.byteLength;
3288	      if (size > MAX_BODY_BYTES) {
3289	        finish('too-large');
3290	        writeResponse(
3291	          res,
3292	          413,
3293	          versionHeaders(activeState.version, {
3294	            'Content-Type': 'text/plain; charset=utf-8',
3295	          }),
3296	          'payload too large\n',
3297	        );
3298	        // 等 413 刷出后再断开，避免客户端收不到响应
3299	        res.once('finish', () => req.socket.destroy());
3300	        return;
3301	      }
3302	      chunks.push(chunk);
3303	    });
3304	    req.on('end', () => finish('received'));
3305	    req.on('error', () => finish('aborted'));
3306	    req.on('aborted', () => finish('aborted'));
3307	    res.on('close', () => finish('aborted'));
3308	  });
3309	}
