function validateBodyWithContentType(
  contentType: string | undefined,
  body: Buffer,
  rule: BodyRule,
): BodyReport | null {
  const mediaType =
    typeof contentType === 'string' ? contentType.split(';', 1)[0].trim().toLowerCase() : '';
