curl -sS -X POST http://127.0.0.1:$PORT/api/order -H 'Content-Type: application/json' -d '{"state":"created"}'; echo
curl -sS -X POST http://127.0.0.1:$PORT/api/order -H 'Content-Type: application/json' -d '{"state":"created"}'; echo
curl -sS -X POST http://127.0.0.1:$PORT/api/order -H 'Content-Type: application/json' -d '{"state":123}'; echo
curl -sS http://127.0.0.1:$PORT/__contractlab/requests | node -e 'let d="";process.stdin.on("data",c=>d+=c).on("end",()=>{const j=JSON.parse(d);for(const r of j.records)console.log(r.id, r.endpoint, "sel="+r.selection, "branch="+r.branch, "pos="+r.sequencePosition, "len="+r.sequenceLength, r.plannedResponse&&r.plannedResponse.body)})'
kill $(cat /tmp/cl-branch/pid)

